+package subsonic
+
+import (
+	"context"
+	"errors"
+	"net/http/httptest"
+
+	"github.com/navidrome/navidrome/core"
+	"github.com/navidrome/navidrome/server/subsonic/responses"
+	. "github.com/onsi/ginkgo/v2"
+	. "github.com/onsi/gomega"
+)
+
+type offsetRecordingStreamer struct {
+	core.MediaStreamer
+	timeOffset int
+}
+
+func (s *offsetRecordingStreamer) NewStream(_ context.Context, _ string, _ string, _ int, timeOffset int) (*core.Stream, error) {
+	s.timeOffset = timeOffset
+	return nil, errors.New("stream creation stopped for test")
+}
+
+var _ = Describe("Stream timeOffset", func() {
+	DescribeTable("passes a valid offset and defaults invalid offsets to zero",
+		func(param string, expected int) {
+			streamer := &offsetRecordingStreamer{}
+			api := &Router{streamer: streamer}
+			_, err := api.Stream(httptest.NewRecorder(), newGetRequest("id=123", param))
+
+			Expect(err).To(MatchError("stream creation stopped for test"))
+			Expect(streamer.timeOffset).To(Equal(expected))
+		},
+		Entry("valid", "timeOffset=42", 42),
+		Entry("missing", "", 0),
+		Entry("malformed", "timeOffset=bad", 0),
+		Entry("negative", "timeOffset=-1", 0),
+	)
+})
+
+var _ = Describe("OpenSubsonicExtensions", func() {
+	It("advertises support for stream offsets", func() {
+		response, err := (&Router{}).GetOpenSubsonicExtensions(nil)
+
+		Expect(err).ToNot(HaveOccurred())
+		Expect(*response.OpenSubsonicExtensions).To(ContainElement(responses.OpenSubsonicExtension{
+			Name: "transcodeOffset", Versions: []int32{1},
+		}))
+	})
+})
